/**
 * @method
 * @name scwin.getCheckedValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getCheckedValue = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetCheckedValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    let checkedValue = '';
    for(let i=0; i<_obj.getItemCount(); i++){
        if(_obj[i].checked){
            checkedValue = _obj[i].value;
            break;
        }
    }
    return checkedValue;
    /* sdd-asis-lifecycle:end */
};
